  #region Enums
  /// <summary>
  /// Structure of agent view
  /// </summary>
  public enum AgentView {
    /// <summary>
    /// Unspecified agent view: the view is defined by the call:
    /// &lt;ul>
    ///   &lt;li>CreateAgent: AGENT_VIEW_SHALLOW&lt;/li>
    ///   &lt;li>UpdateAgent: AGENT_VIEW_SHALLOW&lt;/li>
    ///   &lt;li>GetAgent: AGENT_VIEW_FULL&lt;/li>
    ///   &lt;li>ListAgents: AGENT_VIEW_SHALLOW&lt;/li>
    /// &lt;/ul>
    /// </summary>
    [pbr::OriginalName("AGENT_VIEW_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Full agent view: populate all the fields of the Agent message including configs.
    /// </summary>
    [pbr::OriginalName("AGENT_VIEW_FULL")] Full = 1,
    /// <summary>
    /// Shallow agent view: populates all the fields except configs.
    /// </summary>
    [pbr::OriginalName("AGENT_VIEW_SHALLOW")] Shallow = 2,
    /// <summary>
    /// Minimum view including only agent UUID and agent display name
    /// </summary>
    [pbr::OriginalName("AGENT_VIEW_MINIMUM")] Minimum = 3,
  }

  /// <summary>
  /// Defines when to initiate newly created agent when training started
  /// </summary>
  public enum InitiationProtocol {
    /// <summary>
    /// after cache successfully built and after each model trained the agent will be updated
    /// </summary>
    [pbr::OriginalName("AS_SOON_AS_POSSIBLE")] AsSoonAsPossible = 0,
    /// <summary>
    /// after cache successfully built and all the active models successfully trained
    /// </summary>
    [pbr::OriginalName("WHEN_TRAINED")] WhenTrained = 1,
    /// <summary>
    /// do not initiate
    /// </summary>
    [pbr::OriginalName("NEVER")] Never = 2,
  }

  /// <summary>
  /// Type of reports about the domain of the agent
  /// </summary>
  public enum ReportType {
    /// <summary>
    /// will return all reports as files of specified format compressed into a single zipfile
    /// </summary>
    [pbr::OriginalName("ALL")] All = 0,
    /// <summary>
    /// statistics of the language specific part of the intent database
    /// </summary>
    [pbr::OriginalName("INTENT_PER_LANGUAGE")] IntentPerLanguage = 1,
    /// <summary>
    /// statistics of the language specific part of the entity database
    /// </summary>
    [pbr::OriginalName("ENTITY_PER_LANGUAGE")] EntityPerLanguage = 2,
    /// <summary>
    /// report on collision of the entity synonyms
    /// </summary>
    [pbr::OriginalName("ENTITY_COLLISION")] EntityCollision = 3,
    /// <summary>
    /// report of statistics of the general (relevant to all supported languages) part of intent database
    /// </summary>
    [pbr::OriginalName("INTENT_GENERAL")] IntentGeneral = 4,
    /// <summary>
    /// Aggregate LLM token usage (input / output / cache) over the agent domain.
    /// </summary>
    [pbr::OriginalName("AGENT_LLM_TOKEN_USAGE")] AgentLlmTokenUsage = 5,
    /// <summary>
    /// Per-model usage rollup (calls, tokens, latency) over the agent domain.
    /// </summary>
    [pbr::OriginalName("AGENT_LLM_MODELS_USED")] AgentLlmModelsUsed = 6,
    /// <summary>
    /// Per-provider usage rollup over the agent domain.
    /// </summary>
